function editorRoots(){const editor=$('#editor');if(!editor)return [];const roots=[...editor.querySelectorAll(':scope > [data-beat-id]')].map(block=>({beatId:block.dataset.beatId,root:beatHighlights?block.querySelector('.beat-text'):block})).filter(x=>x.root);return roots.length||beatHighlights?roots:[{beatId:readEditorBeats()[0].id,root:editor}];}
function hideSpellingPopup(){const el=$('#spelling-popup');if(el)el.hidden=true;liveSpellingChoice=null;}
