    const bounds=textViewport();if(bounds&&e.clientY>=bounds.top&&e.clientY<=bounds.bottom){const issue=liveSpelling.find(i=>[...i.range.getClientRects()].some(r=>e.clientX>=r.left-3&&e.clientX<=r.right+3&&e.clientY>=r.top-3&&e.clientY<=r.bottom+5));if(issue){openSpellingPopup(issue);return;}}
