  if(aiEdit.body.html){const c=find(entryId);aiEdit={id:uuid(),base:null,body:{...aiEdit.body,html:'',sourceRevision:c.revision.id},edits:0,saved:0};aiReviewId=null;$('#ai-review').hidden=true;}
