  'selection-rephrase':()=>showSelectionOptions('rephrase',selectedPassage),'selection-synonyms':()=>showSelectionOptions('synonyms',selectedPassage),'selection-retry':generateSelectionOptions,'selection-use':el=>applySelectionOption(Number(el.dataset.index)),
  'edit-beat-plan':el=>editBeatDetails(el.dataset.id),'edit-selection':()=>showWritingTask('selection',selectedPassage?.beatId,selectedPassage),
